def load() -> pd.DataFrame:
    import pandas as pd
    import numpy as np

    path = 'data/biomedical/input/1-s2.0-S0092867420301070-mmc3.xlsx'

    # Load all sheets; identify gene and FDR-like columns; stack into long form
    xls = pd.ExcelFile(path)
    records = []
    for sheet in xls.sheet_names:
        try:
            df = pd.read_excel(path, sheet_name=sheet)
        except Exception:
            continue
        if df is None or df.empty:
            continue

        # Normalize column names
        cols = [str(c).strip() for c in df.columns]
        df.columns = cols

        # Find a gene column (prefer exact 'Gene' then anything containing 'gene')
        gene_col = None
        for c in cols:
            if c.lower() == 'gene':
                gene_col = c
                break
        if gene_col is None:
            for c in cols:
                if 'gene' in c.lower():
                    gene_col = c
                    break
        if gene_col is None:
            continue

        # Find an FDR column (prefer exact 'FDR' then contains 'fdr')
        fdr_col = None
        for c in cols:
            if c.lower() == 'fdr':
                fdr_col = c
                break
        if fdr_col is None:
            for c in cols:
                if 'fdr' in c.lower():
                    fdr_col = c
                    break
        if fdr_col is None:
            continue

        out = df[[gene_col, fdr_col]].copy()
        out.rename(columns={gene_col: 'gene', fdr_col: 'fdr'}, inplace=True)
        out['sheet'] = sheet

        # Coerce
        out['gene'] = out['gene'].astype(str).str.strip()
        out['fdr'] = pd.to_numeric(out['fdr'], errors='coerce')

        # Keep plausible values
        out = out[(out['gene'].notna()) & (out['gene'] != '')]
        out = out[out['fdr'].notna()]
        # some sheets might use percent; keep within [0,1] else drop
        out = out[(out['fdr'] >= 0) & (out['fdr'] <= 1)]

        if not out.empty:
            records.append(out)

    if not records:
        return pd.DataFrame({'gene': [], 'fdr': [], 'sheet': []})

    res = pd.concat(records, ignore_index=True)
    return res
